entries[30312] = { ["name"] = "Teufelseisenmuskete", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSchwerer Griff , Teufelseisengehäuse (3), Eine Handvoll Teufelseisenbolzen (6)\nTeufelseisenmuskete\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n152 - 284 Schaden Tempo 2.80\n(77.86 Schaden pro Sekunde)\n+46 Ausdauer\nHaltbarkeit 85 / 85\n63" }
