entries[30455] = { ["name"] = "Eislanze", ["text"] = "1% von Grundmana 40 Meter Reichweite\nSofort\nFügt einem gegnerischen Ziel 349 [ Glyphe 'Zersplitterndes Eis' : und einem zweiten Ziel in der Nähe ( 306 * 50 / 100) bis ( 392 * 50 / 100) ] [ und einem zweiten Ziel in der Nähe [ 306 * ((1.25 * ((1 + (( 90 > 79 ? 1 : 0)) * 0)))) * 50 / 100] bis [ 392 * ((1.25 * ((1 + (( 90 > 79 ? 1 : 0)) * 0)))) * 50 / 100] ] Frostschaden zu.\n\nDer Schaden von 'Eislanze' gegen eingefrorene Ziele wird vervierfacht." }
