entries[30474] = { ["name"] = "Blutdurst", ["text"] = "Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nGreift das Ziel sofort an und verursacht 120% normalen Waffenschaden. Zusätzlich regeneriert der Zaubernde durch die nächsten 5 erfolgreichen Nahkampfangriffe 238 bis 262 Gesundheit. Dieser Effekt hält 10 Sek. lang an." }
