entries[30548] = { ["name"] = "Schockdrosselnder Partikelextraktor", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nTeufelseisengehäuse (2), Eine Handvoll Teufelseisenbolzen (2), Urleben (4), Empfindlicher Arkanitwandler\nEinzigartig\nBenötigt Ingenieurskunst\n(305)\nBenutzen: Extrahiert Gas aus einer in der Nähe befindlichen Gaswolke.\nZeigt die Position aller nahen Gaswolken auf der Minikarte an, solang sich der Partikelextraktor in Eurem Inventar befindet." }
