entries[30574] = { ["name"] = "Gnomische Machtschutzbrille", ["text"] = "Wirken in 15 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nZauberstoff (4), Urfeuer (8), Urluft (8), Urerde (8), Urwasser (8), Talasit (2)\nGnomische Machtschutzbrille\nWird beim Aufheben gebunden\nKopf Stoff\n279 Rüstung\n+32 Ausdauer\n+50 Intelligenz\nErhöht Eure kritische Trefferwertung um + 28.\nHaltbarkeit 100 / 100\nBenötigt Ingenieurskunst\n(375)\nBenötigt Gnomeningenieur" }
entries[30575] = { ["name"] = "Gnomische Kampfschutzbrille", ["text"] = "Wirken in 15 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nSchweres Knotenhautleder (8), Urschatten (12), Urerde (12), Urfeuer (12), Lebendiger Rubin (2)\nGnomische Kampfschutzbrille\nWird beim Aufheben gebunden\nKopf Leder\n391 Rüstung\n+50 Beweglichkeit\n+21 Ausdauer\nErhöht Eure kritische Trefferwertung um + 28.\nHaltbarkeit 100 / 100\nBenötigt Ingenieurskunst\n(375)\nBenötigt Gnomeningenieur" }
entries[30584] = { ["name"] = "Furcht", ["text"] = "Sofort\nErfüllt in der Nähe befindliche Feinde mit Furcht, woraufhin diese bis zu 3 Sek. lang voller Schrecken flüchten." }
